    avlInsert(root->right, item);
} else {
    return; // Duplicate items not allowed in this AVL implementation
}

int balance = 0;
if (root->left != nullptr) {
    balance += 1; // Simplified height check or use a height() helper
}
if (root->right != nullptr) {
    balance -= 1;
}

// In a standard AVL, we calculate balance factor as height(left) - height(right)
auto getHeight = [](auto self, TreeNode* node) -> int {
    return node == nullptr ? -1 : 1 + std::max(self(self, node->left), self(self, node->right));
};

int bf = getHeight(getHeight, root->left) - getHeight(getHeight, root->right);

if (bf > 1) {
    if (getHeight(getHeight, root->left->left) >= getHeight(getHeight, root->left->right)) {
        avlRotateRight(root);
